function renderReviews(){if(!$('#review-history'))return;$('#review-history').textContent=reviews.length?reviews.map(r=>'运行 '+r.runId+' / 输入修订 '+r.inputRevision+' · '+(r.runId===runId&&r.inputRevision===inputRevision&&status==='complete'?'当前确认':'历史确认，当前需重核')+'：'+r.note).join('\n'):'尚无人工确认。';}
